    [Fact]
    public async Task GetAllAsync_ShouldReturnAllCatalogItems()
    {
        // Arrange
        using var context = new CatalogDbContext(_options);
        var repository = new CatalogItemRepository(context, _mockLogger.Object);

        context.CatalogItems.AddRange(
            new CatalogItem { Id = 1, Name = "Item 1", Price = 10m },
            new CatalogItem { Id = 2, Name = "Item 2", Price = 20m }
        );
        await context.SaveChangesAsync();

        // Act
        var result = await repository.GetAllAsync();

        // Assert
        Assert.NotNull(result);
        Assert.Equal(2, result.Count());
    }

    [Fact]
    public async Task GetByIdAsync_ShouldReturnCatalogItem_WhenExists()
    {
        // Arrange
        using var context = new CatalogDbContext(_options);
        var repository = new CatalogItemRepository(context, _mockLogger.Object);

        var catalogItem = new CatalogItem { Id = 1, Name = "Test Item", Price = 50m };
        context.CatalogItems.Add(catalogItem);
        await context.SaveChangesAsync();

        // Act
        var result = await repository.GetByIdAsync(1);

