    public async Task UpdateAsync_ShouldUpdateCatalogItem()
    {
        // Arrange
        using var context = new CatalogDbContext(_options);
        var repository = new CatalogItemRepository(context, _mockLogger.Object);

        var catalogItem = new CatalogItem { Id = 1, Name = "Original", Price = 50m };
        context.CatalogItems.Add(catalogItem);
        await context.SaveChangesAsync();
        context.Entry(catalogItem).State = EntityState.Detached;

        // Act
        catalogItem.Name = "Updated";
        await repository.UpdateAsync(catalogItem);

        // Assert
        var updated = await context.CatalogItems.FindAsync(1);
        Assert.NotNull(updated);
        Assert.Equal("Updated", updated.Name);
