    private readonly Mock<ILogger<CatalogTypeRepository>> _mockLogger;
    private readonly DbContextOptions<CatalogDbContext> _options;

    public CatalogTypeRepositoryTests()
    {
        _mockLogger = new Mock<ILogger<CatalogTypeRepository>>();
        _options = new DbContextOptionsBuilder<CatalogDbContext>()
            .UseInMemoryDatabase(databaseName: Guid.NewGuid().ToString())
            .Options;
    }

    [Fact]
    public void Constructor_ShouldThrowArgumentNullException_WhenContextIsNull()
    {
        // Act & Assert
        Assert.Throws<ArgumentNullException>(() =>
            new CatalogTypeRepository(null!, _mockLogger.Object));
    }

    [Fact]
    public void Constructor_ShouldThrowArgumentNullException_WhenLoggerIsNull()
    {
        // Arrange
        using var context = new CatalogDbContext(_options);

        // Act & Assert
        Assert.Throws<ArgumentNullException>(() =>
            new CatalogTypeRepository(context, null!));
    }

    [Fact]
    public async Task GetAllAsync_ShouldReturnAllCatalogTypes()
    {
        // Arrange
        using var context = new CatalogDbContext(_options);
        var repository = new CatalogTypeRepository(context, _mockLogger.Object);

        context.CatalogTypes.AddRange(
            new CatalogType { Id = 1, Type = "Type 1" },
            new CatalogType { Id = 2, Type = "Type 2" }
        );
        await context.SaveChangesAsync();

        // Act
        var result = await repository.GetAllAsync();

        // Assert
        Assert.NotNull(result);
        Assert.Equal(2, result.Count());
    }

    [Fact]
    public async Task GetByIdAsync_ShouldReturnCatalogType_WhenExists()
    {
        // Arrange
        using var context = new CatalogDbContext(_options);
        var repository = new CatalogTypeRepository(context, _mockLogger.Object);

        var catalogType = new CatalogType { Id = 1, Type = "Electronics" };
        context.CatalogTypes.Add(catalogType);
        await context.SaveChangesAsync();

        // Act
        var result = await repository.GetByIdAsync(1);

        // Assert
        Assert.NotNull(result);
        Assert.Equal(1, result.Id);
        Assert.Equal("Electronics", result.Type);
    }

    [Fact]
    public async Task GetByIdAsync_ShouldReturnNull_WhenNotExists()
    {
        // Arrange
        using var context = new CatalogDbContext(_options);
        var repository = new CatalogTypeRepository(context, _mockLogger.Object);

        // Act
        var result = await repository.GetByIdAsync(999);

        // Assert
        Assert.Null(result);
    }

    [Fact]
    public async Task AddAsync_ShouldAddCatalogType()
    {
        // Arrange
        using var context = new CatalogDbContext(_options);
        var repository = new CatalogTypeRepository(context, _mockLogger.Object);
        var catalogType = new CatalogType { Type = "Clothing" };

        // Act
        var result = await repository.AddAsync(catalogType);

        // Assert
        Assert.True(result > 0);
        Assert.Equal(1, await context.CatalogTypes.CountAsync());
    }

    [Fact]
    public async Task UpdateAsync_ShouldUpdateCatalogType()
    {
        // Arrange
        using var context = new CatalogDbContext(_options);
        var repository = new CatalogTypeRepository(context, _mockLogger.Object);

        var catalogType = new CatalogType { Id = 1, Type = "Original" };
        context.CatalogTypes.Add(catalogType);
        await context.SaveChangesAsync();
        context.Entry(catalogType).State = EntityState.Detached;

        // Act
        catalogType.Type = "Updated";
        await repository.UpdateAsync(catalogType);

        // Assert
        var updated = await context.CatalogTypes.FindAsync(1);
        Assert.NotNull(updated);
        Assert.Equal("Updated", updated.Type);
    }

    [Fact]
    public async Task DeleteAsync_ShouldDeleteCatalogType_WhenExists()
    {
        // Arrange
        using var context = new CatalogDbContext(_options);
        var repository = new CatalogTypeRepository(context, _mockLogger.Object);

        var catalogType = new CatalogType { Id = 1, Type = "To Delete" };
        context.CatalogTypes.Add(catalogType);
        await context.SaveChangesAsync();

        // Act
        await repository.DeleteAsync(1);

        // Assert
        Assert.Equal(0, await context.CatalogTypes.CountAsync());
    }

    [Fact]
    public async Task DeleteAsync_ShouldNotThrow_WhenItemDoesNotExist()
    {
        // Arrange
        using var context = new CatalogDbContext(_options);
        var repository = new CatalogTypeRepository(context, _mockLogger.Object);

        // Act & Assert
        await repository.DeleteAsync(999); // Should not throw
    }

    [Fact]
    public async Task ExistsAsync_ShouldReturnTrue_WhenTypeExists()
    {
        // Arrange
        using var context = new CatalogDbContext(_options);
        var repository = new CatalogTypeRepository(context, _mockLogger.Object);

        context.CatalogTypes.Add(new CatalogType { Id = 1, Type = "Existing Type" });
        await context.SaveChangesAsync();

        // Act
        var result = await repository.ExistsAsync(1);

        // Assert
        Assert.True(result);
    }

    [Fact]
    public async Task ExistsAsync_ShouldReturnFalse_WhenTypeDoesNotExist()
    {
        // Arrange
        using var context = new CatalogDbContext(_options);
        var repository = new CatalogTypeRepository(context, _mockLogger.Object);

        // Act
        var result = await repository.ExistsAsync(999);

        // Assert
        Assert.False(result);
    }
}

