     1→using eShopMigrated.Domain.Interfaces.Repositories;
     2→using eShopMigrated.Domain.Interfaces.Services;
     3→using eShopMigrated.Web.ViewModels;
     4→using Microsoft.AspNetCore.Mvc;
     5→using Microsoft.AspNetCore.Mvc.RazorPages;
     6→
     7→namespace eShopMigrated.Web.Pages.Catalog;
     8→
     9→public class IndexModel : PageModel
    10→{
    11→    private readonly ICatalogItemService _catalogItemService;
    12→    private readonly ICatalogBrandRepository _brandRepository;
    13→    private readonly ICatalogTypeRepository _typeRepository;
    14→    private readonly ILogger<IndexModel> _logger;
    15→    private const int PageSize = 10;
    16→
    17→    public IndexModel(
    18→        ICatalogItemService catalogItemService,
    19→        ICatalogBrandRepository brandRepository,
    20→        ICatalogTypeRepository typeRepository,
    21→        ILogger<IndexModel> logger)
    22→    {
    23→        _catalogItemService = catalogItemService;
    24→        _brandRepository = brandRepository;
    25→        _typeRepository = typeRepository;
    26→        _logger = logger;
    27→    }
    28→
    29→    public PaginatedCatalogItemsViewModel PaginatedItems { get; set; } = new();
    30→
    31→    public async Task<IActionResult> OnGetAsync(int? pageIndex)
    32→    {
    33→        try
    34→        {
    35→            var currentPageIndex = pageIndex ?? 0;
    36→            _logger.LogInformation("Loading catalog page {PageIndex}", currentPageIndex);
    37→
    38→            var (items, totalCount, totalPages) = await _catalogItemService.GetPaginatedAsync(
    39→                currentPageIndex, PageSize);
    40→
    41→            var brands = await _brandRepository.GetAllAsync();
    42→            var types = await _typeRepository.GetAllAsync();
    43→
    44→            var brandDictionary = brands.ToDictionary(b => b.Id, b => b.Brand);
    45→            var typeDictionary = types.ToDictionary(t => t.Id, t => t.Type);
    46→
    47→            PaginatedItems = new PaginatedCatalogItemsViewModel
    48→            {
    49→                CatalogItems = items.Select(item => new CatalogItemViewModel
    50→                {
    51→                    Id = item.Id,
    52→                    Name = item.Name,
    53→                    Description = item.Description,
    54→                    Price = item.Price,
    55→                    PictureFileName = item.PictureFileName,
    56→                    CatalogTypeId = item.CatalogTypeId,
    57→                    CatalogBrandId = item.CatalogBrandId,
    58→                    AvailableStock = item.AvailableStock,
    59→                    RestockThreshold = item.RestockThreshold,
    60→                    MaxStockThreshold = item.MaxStockThreshold,
    61→                    OnReorder = item.OnReorder,
    62→                    CatalogTypeName = typeDictionary.GetValueOrDefault(item.CatalogTypeId),
    63→                    CatalogBrandName = brandDictionary.GetValueOrDefault(item.CatalogBrandId)
    64→                }).ToList(),
