using Xunit;
using Moq;
using eShopMigrated.Web.Pages.Catalog;
using eShopMigrated.Domain.Interfaces.Services;
using eShopMigrated.Domain.Interfaces.Repositories;
using eShopMigrated.Domain.Entities;
using Microsoft.Extensions.Logging;
using Microsoft.AspNetCore.Mvc;

namespace eShopMigrated.Web.Pages.Catalog.Tests;

public class IndexModelTests
{
    private readonly Mock<ICatalogItemService> _mockService;
    private readonly Mock<ICatalogBrandRepository> _mockBrandRepo;
    private readonly Mock<ICatalogTypeRepository> _mockTypeRepo;
    private readonly Mock<ILogger<IndexModel>> _mockLogger;
    private readonly IndexModel _model;

    public IndexModelTests()
    {
        _mockService = new Mock<ICatalogItemService>();
        _mockBrandRepo = new Mock<ICatalogBrandRepository>();
        _mockTypeRepo = new Mock<ICatalogTypeRepository>();
        _mockLogger = new Mock<ILogger<IndexModel>>();
        _model = new IndexModel(_mockService.Object, _mockBrandRepo.Object, _mockTypeRepo.Object, _mockLogger.Object);
    }

    [Fact]
    public async Task OnGetAsync_ShouldReturnPageResult()
    {
        // Arrange
        var items = new List<CatalogItem>
        {
            new CatalogItem { Id = 1, Name = "Item 1", Price = 10m, CatalogBrandId = 1, CatalogTypeId = 1 }
        };
        _mockService.Setup(s => s.GetPaginatedAsync(0, 10, default))
            .ReturnsAsync((items, 1L, 1));
        _mockBrandRepo.Setup(r => r.GetAllAsync(default))
            .ReturnsAsync(new List<CatalogBrand> { new CatalogBrand { Id = 1, Brand = "Brand1" } });
        _mockTypeRepo.Setup(r => r.GetAllAsync(default))
            .ReturnsAsync(new List<CatalogType> { new CatalogType { Id = 1, Type = "Type1" } });

        // Act
        var result = await _model.OnGetAsync(null);

        // Assert
        Assert.IsType<PageResult>(result);
    }

    [Fact]
    public async Task OnGetAsync_ShouldLoadPaginatedItems()
    {
        // Arrange
        var items = new List<CatalogItem>
        {
            new CatalogItem { Id = 1, Name = "Item 1", Price = 10m, CatalogBrandId = 1, CatalogTypeId = 1 }
        };
        _mockService.Setup(s => s.GetPaginatedAsync(0, 10, default))
            .ReturnsAsync((items, 1L, 1));
        _mockBrandRepo.Setup(r => r.GetAllAsync(default))
            .ReturnsAsync(new List<CatalogBrand> { new CatalogBrand { Id = 1, Brand = "Brand1" } });
        _mockTypeRepo.Setup(r => r.GetAllAsync(default))
            .ReturnsAsync(new List<CatalogType> { new CatalogType { Id = 1, Type = "Type1" } });

        // Act
        await _model.OnGetAsync(null);

        // Assert
        Assert.NotNull(_model.PaginatedItems);
        Assert.Single(_model.PaginatedItems.CatalogItems);
    }

    [Fact]
    public async Task OnGetAsync_ShouldHandlePageIndex()
    {
        // Arrange
        var items = new List<CatalogItem>();
        _mockService.Setup(s => s.GetPaginatedAsync(2, 10, default))
            .ReturnsAsync((items, 0L, 0));
        _mockBrandRepo.Setup(r => r.GetAllAsync(default))
            .ReturnsAsync(new List<CatalogBrand>());
        _mockTypeRepo.Setup(r => r.GetAllAsync(default))
            .ReturnsAsync(new List<CatalogType>());

        // Act
        await _model.OnGetAsync(2);

        // Assert
        _mockService.Verify(s => s.GetPaginatedAsync(2, 10, default), Times.Once);
    }

    [Fact]
    public async Task OnGetAsync_ShouldRedirectToErrorOnException()
    {
        // Arrange
        _mockService.Setup(s => s.GetPaginatedAsync(It.IsAny<int>(), It.IsAny<int>(), default))
            .ThrowsAsync(new Exception("Test exception"));

        // Act
        var result = await _model.OnGetAsync(null);

        // Assert
        var redirectResult = Assert.IsType<RedirectToPageResult>(result);
        Assert.Equal("/Error", redirectResult.PageName);
    }
}

