using Xunit;
using eShopMigrated.Infrastructure.Extensions;
using eShopMigrated.Domain.Interfaces.Repositories;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Configuration;

namespace eShopMigrated.Infrastructure.Extensions.Tests;

public class ServiceCollectionExtensionsTests
{
    [Fact]
    public void AddInfrastructureServices_ShouldRegisterRepositories()
    {
        // Arrange
        var services = new ServiceCollection();
        var configuration = new ConfigurationBuilder()
            .AddInMemoryCollection(new Dictionary<string, string?>
            {
                ["ConnectionStrings:CatalogConnection"] = "Server=test;Database=test;Trusted_Connection=true;"
            })
            .Build();

        // Act
        services.AddInfrastructureServices(configuration);
        var serviceProvider = services.BuildServiceProvider();

        // Assert
        var catalogItemRepository = serviceProvider.GetService<ICatalogItemRepository>();
        var catalogBrandRepository = serviceProvider.GetService<ICatalogBrandRepository>();
        var catalogTypeRepository = serviceProvider.GetService<ICatalogTypeRepository>();

        Assert.NotNull(catalogItemRepository);
        Assert.NotNull(catalogBrandRepository);
        Assert.NotNull(catalogTypeRepository);
    }

    [Fact]
    public void AddInfrastructureServices_ShouldReturnServiceCollection()
    {
        // Arrange
        var services = new ServiceCollection();
        var configuration = new ConfigurationBuilder()
            .AddInMemoryCollection(new Dictionary<string, string?>
            {
                ["ConnectionStrings:CatalogConnection"] = "Server=test;Database=test;Trusted_Connection=true;"
            })
            .Build();

        // Act
        var result = services.AddInfrastructureServices(configuration);

        // Assert
        Assert.NotNull(result);
        Assert.Same(services, result);
    }

    [Fact]
    public void AddInfrastructureServices_ShouldRegisterDbContext()
    {
        // Arrange
        var services = new ServiceCollection();
        var configuration = new ConfigurationBuilder()
            .AddInMemoryCollection(new Dictionary<string, string?>
            {
                ["ConnectionStrings:CatalogConnection"] = "Server=test;Database=test;Trusted_Connection=true;"
            })
            .Build();

        // Act
        services.AddInfrastructureServices(configuration);

        // Assert
        Assert.Contains(services, sd => sd.ServiceType.Name.Contains("CatalogDbContext"));
    }
}

